function tag(text:string,cls=''){return `<span class="tag ${cls}">${text}</span>`}
function scoresHTML(r:Report){
 const fallback:Record<Category,[string,string]>={
  overview:['رتّب أولوياتك ولا تحمل نفسك أكثر من خطوة مهمة.','Set one clear priority and avoid overloading the day.'],
  career:['راجع مهمة العمل الأهم وخلي قرارك مبني على نتيجة واضحة.','Review the most important task and judge it by results.'],
  love:['شوف التواصل الحقيقي قبل ما تعتمد على إحساس الإعجاب.','Check real communication before drawing romantic conclusions.'],
  communication:['اختار كلام مباشر واسمع الرد بدون ما تقرأ ما بين السطور زيادة.','Communicate plainly and listen rather than overinterpreting silence.'],
  energy:['وزّع مجهودك بين الحركة والراحة بدل الاندفاع دفعة وحدة.','Pace your activity and rest instead of spending all your energy at once.'],
  emotions:['سمِّ شعورك الفعلي قبل ما تبني قرار عليه.','Name what you actually feel before acting on it.'],
  recovery:['خلّ الراحة والنوم جزء من جدولك مو شي تأجله.','Give rest and sleep a planned place in your day.'],
  timing:['تأكد من الموعد والتفاصيل واترك هامش للتغيير.','Verify the timing and leave room for adjustments.']
 };
 return '<div class="scores-grid rich-scores">'+categories.map(c=>{const signal=r.signals.find(s=>s.category===c),v=r.scores[c],line=signal?copy(signal).action:t(...fallback[c]);return '<button class="score-card '+gaugeLevel(v)+'" data-category="'+c+'"><span class="score-symbol '+c+'">'+categoryLabels[c][2]+'</span><span class="score-number">'+v+'<small>/100</small></span><b>'+cat(c)+'</b><p>'+esc(line)+'</p><div class="meter"><i style="width:'+v+'%"></i></div></button>'}).join('')+'</div>';
}
function signalCard(s:Signal,index:number){const text=copy(s);return `<button class="signal-card ${s.tone}" data-signal="${index}"><span class="signal-icon">${categoryLabels[s.category][2]}</span><div><div class="signal-meta">${cat(s.category)} <span>·</span> ${tone(s)}</div><h3>${text.title}</h3><div class="direct-advice"><p class="good"><b>${t("الزين","Good")}</b>${text.good}</p><p class="careful"><b>${t("انتبه","Watch out")}</b>${text.careful}</p><p class="do"><b>${t("سوي هالشي","Do this")}</b>${text.action}</p></div><small>${t('اعرض الدليل','See evidence')} <span class="arrow">↗</span></small></div></button>`}
function today(){const r=data!,primary=r.signals[0],text=primary?copy(primary):null;return `<div class="dashboard-grid"><div class="main-column"><section class="hero panel"><div class="hero-top"><span class="live-label"><i class="status-dot"></i>${t('هسّه · إيقاع اللحظة','NOW · THE MOMENT')}</span><span class="subtle">${dateText(selected,{hour:'2-digit',minute:'2-digit'})}</span></div><div class="hero-copy">${tag(t('مرحباً','Welcome')+' '+esc(active.name),'violet')}<h2>${text?.title??t('خذ مساحة وشوف الصورة','Make room for the bigger picture')}</h2><p>${text?.action??t('ماكو إشارة مهيمنة ضمن الأورب المحدد.','No dominant contact within the configured orbs.')}</p><div class="hero-bottom"><button class="primary" data-go="evidence">${t('ليش هاي القراءة؟','Why this reading?')} <span>↗</span></button><span class="subtle">${t('نصيحتك لهالوقت','Guidance for this moment')}</span></div></div><div class="hero-orbit" aria-hidden="true"><i></i><i></i><i></i><span>✦</span><b>☾</b><em>·</em></div></section>${scoresHTML(r)}<div class="section-title"><h2>${t('إشارات تستحق انتباهك','Signals worth your attention')}</h2><button class="text-button" data-go="signals">${t('كل الإشارات','All signals')} ↗</button></div><div class="signal-list">${distinctHighlights(r.signals,copy,3,1).map(({item,index})=>signalCard(item,index)).join('')||`<p class="empty panel">${t('ماكو إشارات إضافية مختلفة عن القراءة الرئيسية ضمن الأورب المحدد.','No additional distinct signals beyond the headline reading within the configured orbs.')}</p>`}</div><section class="panel rhythm"><div class="section-title"><div><span class="eyebrow">${t('خلال الـ 24 ساعة الجاية','THE NEXT 24 HOURS')}</span><h2>${t('شلون يتغيّر الإيقاع؟','How does the rhythm shift?')}</h2></div>${tag(t('مؤشر رمزي','Symbolic index'))}</div>${trend(24)}<button class="text-button" data-go="time">${t('استكشف وقت ثاني بآلة الزمن','Explore another moment in Time Machine')} ↗</button></section></div><aside class="right-column"><section class="panel sky-card"><div class="section-title"><h2>${t('سماء اللحظة','The sky, now')}</h2>${tag('LIVE','cyan')}</div>${wheel(r.current)}<div class="sky-summary">${r.current.points.slice(0,3).map(p=>`<div><span>${p.symbol} ${planet(p.id)}</span><b>${signName(p.longitude)}</b><small>${(p.longitude%30).toFixed(2)}° ${p.speed<0?'℞':''}</small></div>`).join('')}</div><button class="text-button" data-go="chart">${t('افتح الخارطة الكاملة','Open the full chart')} ↗</button></section><section class="panel lunar-card"><span class="moon-glyph">☾</span><span class="eyebrow">${t('القمر وخارطتك','THE MOON & YOUR CHART')}</span><h3>${signName(r.current.points.find(p=>p.id==='Moon')!.longitude)}</h3><p>${t('شوف موضع القمر واتصالاته المحسوبة بخارطتك الأصلية.','Explore the Moon’s calculated position and contacts with your natal chart.')}</p><button class="text-button" data-go="evidence">${t('شوف التفاصيل','View details')} ↗</button></section><button class="panel time-shortcut" data-go="time"><span>◷</span><div><b>${t('آلة الزمن','Time Machine')}</b><p>${t('أي تاريخ. منظور جديد.','Another date. A new perspective.')}</p></div><b>↗</b></button></aside></div>`}
function trend(hours:number){const rows=Array.from({length:9},(_,i)=>{const at=new Date(Math.min(Date.UTC(2399,11,31,23,59),+selected+i*hours/8*3600000));return {at,value:average(getReport(at))}});const pts=rows.map((r,i)=>`${i*75},${130-r.value}`).join(' ');return `<div class="trend"><svg viewBox="0 0 600 150" role="img" aria-label="${t('مؤشر رمزي محسوب عبر الوقت','Calculated symbolic index over time')}"><defs><linearGradient id="area" x2="0" y2="1"><stop stop-color="#8272df" stop-opacity=".25"/><stop offset="1" stop-color="#8272df" stop-opacity="0"/></linearGradient></defs>${[25,50,75,100].map(v=>`<line x1="0" x2="600" y1="${130-v}" y2="${130-v}" stroke="#292d43" stroke-dasharray="3 5"/><text x="3" y="${126-v}" fill="#727993" font-size="8">${v}</text>`).join('')}<polygon points="0,140 ${pts} 600,140" fill="url(#area)"/><polyline points="${pts}" stroke="#a79aef" stroke-width="2" fill="none"/>${rows.map((r,i)=>`<circle cx="${i*75}" cy="${130-r.value}" r="3" fill="#c6bbff"><title>${dateText(r.at,{hour:'2-digit',minute:'2-digit'})}: ${r.value}/100</title></circle>`).join('')}</svg><div class="trend-labels" dir="ltr">${rows.filter((_,i)=>i%2===0).map(r=>`<span>${dateText(r.at,{hour:'2-digit',minute:'2-digit'})}</span>`).join('')}</div></div>`}
function signalsPage(){const r=data!;return `<div class="filter-row">${(['all',...categories] as const).map(c=>`<button data-filter="${c}" class="chip ${filter===c?'selected':''}">${c==='all'?t('الكل','All'):cat(c)}</button>`).join('')}</div><div class="signal-list wide">${r.signals.map((s,i)=>filter==='all'||filter===s.category?signalCard(s,i):'').join('')||`<div class="empty panel">${t('ماكو إشارة لهالمجال ضمن الأورب المحدد.','No signal in this category within the configured orbs.')}</div>`}</div><section class="panel rhythm"><h2>${t('تغيّر المؤشر عبر اليوم','Index through the day')}</h2>${trend(24)}</section>`}
